/// Single entry point the rest of the app uses to talk to the Python sidecar.
///
/// Innermost layer: it must not import `core` or `features` (see `AGENTS.md`
/// "Architecture" and `docs/technology-stack.md` §5 — `features -> core -> api`).
///
/// It wraps the OpenAPI-generated `auto_scoring_api` client (dio + built_value,
/// regenerated by `pnpm run openapi:generate`) and owns the cross-cutting
/// concerns the generated code leaves to callers: the per-session bearer token,
/// timeouts, cancellation, and collapsing transport failures into one
/// [SidecarApiException].
library;

import 'dart:typed_data';

import 'package:auto_scoring_api/auto_scoring_api.dart';
import 'package:dio/dio.dart';
import 'package:http_parser/http_parser.dart';

export 'package:auto_scoring_api/auto_scoring_api.dart'
    show
        AnnotationEditRequest,
        AnnotationResponse,
        BoundingBoxResponse,
        CompleteRegistrationResponse,
        CriterionOutcomeRequest,
        CriterionResultResponse,
        DependencyEdgeModel,
        DependencyGraphResponse,
        DependencyProvision,
        ExportRequestResponse,
        ExportResponse,
        GradeResultResponse,
        GradingAvailabilityResponse,
        JobResponse,
        NormalizedBBoxModel,
        NormalizedRectResponse,
        PageFormatModel,
        ProfileResponse,
        QuestionResponse,
        QuestionTextOverride,
        RecognitionResponse,
        RecognitionResponseSlim,
        RegionKind,
        RegionModel,
        ReviewActionResponse,
        ReviewResponse,
        RubricCriterionResponse,
        ScoreRequest,
        ScoreResponse,
        ScoreValueResponse,
        SubmissionResponse,
        TestResponse,
        TestSummary,
        UnresolvedQuestionModel,
        UpdateProfileRequest;
export 'package:dio/dio.dart' show CancelToken;

/// Where the sidecar is listening and the token minted for this session.
///
/// Both values come from the sidecar's startup handshake. Process supervision
/// that produces them lands with the Windows distribution work; until then this
/// is constructed by tests.
class SidecarConnection {
  const SidecarConnection({required this.baseUrl, required this.token});

  /// Origin of the sidecar, e.g. `http://127.0.0.1:52348`.
  final String baseUrl;

  /// Per-session bearer token. Never logged.
  final String token;
}

/// What went wrong with a sidecar call, once transport details are stripped.
enum SidecarErrorKind {
  /// The sidecar could not be reached (not started, wrong port, refused).
  unavailable,

  /// The request outlived its timeout.
  timeout,

  /// The caller cancelled the request via a [CancelToken].
  cancelled,

  /// The sidecar rejected the bearer token (HTTP 401).
  unauthorized,

  /// The sidecar refused a review action (HTTP 409): a stale
  /// `expected_version` (someone else already acted on this question), no AI
  /// grade to approve/edit yet, or nothing left to undo. The caller should
  /// reload this question's review history and let the reviewer retry
  /// (Issue #22 acceptance: "同時/重複requestが…古いversionの更新を拒否する").
  conflict,

  /// The sidecar answered with an error status or an unreadable body.
  badResponse,

  /// Anything else.
  unknown,
}

/// The only exception callers of [SidecarApiClient] need to handle.
class SidecarApiException implements Exception {
  SidecarApiException(
    this.kind,
    this.message, {
    this.statusCode,
    this.unconfirmedQuestionIds,
  });

  final SidecarErrorKind kind;
  final String message;
  final int? statusCode;

  /// Present only for `POST .../export`'s 409 (Issue #23 acceptance: "未確認
  /// 設問がある場合は出力を拒否し、対象を表示する") -- the question ids the
  /// sidecar reports are not yet confirmed. `null` for every other error.
  final List<String>? unconfirmedQuestionIds;

  @override
  String toString() =>
      'SidecarApiException($kind, "$message", status: $statusCode)';
}

/// Raised by [SidecarApiClient.createSubmission] when the sidecar already has
/// a submission with the same PDF content for this test (409) -- Issue #17's
/// reintake policy (docs/answer-intake-and-preprocessing.md §2). Carries the
/// existing submission id so the UI can point the user at it instead of just
/// showing a generic error.
class DuplicateSubmissionException implements Exception {
  DuplicateSubmissionException(this.message, this.existingSubmissionId);

  final String message;
  final String existingSubmissionId;

  @override
  String toString() =>
      'DuplicateSubmissionException("$message", existing: $existingSubmissionId)';
}

/// Thin, typed boundary over the generated sidecar client.
class SidecarApiClient {
  SidecarApiClient(
    SidecarConnection connection, {
    Duration timeout = const Duration(seconds: 10),
    Duration intakeTimeout = const Duration(minutes: 5),
    Dio? dio,
    Dio? uploadDio,
  }) : _dio = dio ?? Dio(),
       _uploadDio = uploadDio ?? Dio() {
    _configure(_dio, connection, timeout);
    _configure(_uploadDio, connection, intakeTimeout);
    // Pass an empty interceptor list so the generated client does not also
    // register its own auth interceptors on top of ours.
    final generated = AutoScoringApi(dio: _dio, interceptors: const []);
    _api = generated.getDefaultApi();
    _testRegistrationApi = generated.getTestRegistrationApi();
    _dependencyGraphApi = generated.getDependencyGraphApi();
    final uploadGenerated = AutoScoringApi(
      dio: _uploadDio,
      interceptors: const [],
    );
    _uploadApi = uploadGenerated.getDefaultApi();
    // Registering a test uploads two PDFs in one request, same rationale as
    // createSubmission below -- it needs the longer intake timeout, not the
    // near-instant default.
    _uploadTestRegistrationApi = uploadGenerated.getTestRegistrationApi();
    _recognitionsApi = generated.getRecognitionsApi();
    _reviewApi = generated.getReviewApi();
    _jobsApi = generated.getJobsApi();
    _exportApi = generated.getExportApi();
  }

  static void _configure(
    Dio dio,
    SidecarConnection connection,
    Duration timeout,
  ) {
    final baseUrl = _validatedLoopbackBaseUrl(connection.baseUrl);
    dio.options
      ..baseUrl = baseUrl
      ..connectTimeout = timeout
      ..sendTimeout = timeout
      ..receiveTimeout = timeout;
    dio.interceptors.add(
      InterceptorsWrapper(
        onRequest: (options, handler) {
          if (options.path != '/healthz') {
            options.headers['Authorization'] = 'Bearer ${connection.token}';
          }
          handler.next(options);
        },
      ),
    );
  }

  final Dio _dio;
  late final DefaultApi _api;
  late final TestRegistrationApi _testRegistrationApi;
  late final DependencyGraphApi _dependencyGraphApi;
  late final RecognitionsApi _recognitionsApi;
  late final ReviewApi _reviewApi;
  late final JobsApi _jobsApi;
  late final ExportApi _exportApi;

  /// A second Dio/client pair, configured with [intakeTimeout] instead of
  /// [timeout], for [createSubmission]. Rasterizing, deskewing and cropping
  /// every page of a large answer PDF happens inside that one request before
  /// the sidecar responds, so it needs far more headroom than the other
  /// (near-instant) calls share -- otherwise the client reports a timeout
  /// failure while the sidecar keeps working and commits anyway, and a
  /// client-side retry on the same bytes would then just surface as a
  /// confusing duplicate-submission conflict.
  final Dio _uploadDio;
  late final DefaultApi _uploadApi;
  late final TestRegistrationApi _uploadTestRegistrationApi;

  /// Liveness probe. Never throws: an unreachable sidecar is a state the UI
  /// renders, not an error. The endpoint itself needs no auth.
  Future<bool> isHealthy({CancelToken? cancelToken}) async {
    try {
      final response = await _api.healthzHealthzGet(cancelToken: cancelToken);
      return response.data?['status'] == 'ok';
    } on DioException {
      return false;
    }
  }

  /// Whether this installation can AI-grade at all, and if not, why
  /// (Issue #97).
  ///
  /// Answers a question no other call can: every grading job on a host with
  /// no credentials fails the same way an unreadable answer does, so without
  /// this the reviewer cannot tell "this machine cannot grade" from "the AI
  /// could not read this one". `reason` names configuration variables and
  /// host prerequisites only -- the sidecar keeps credential *values* out of
  /// it by construction (`api/app.py` の `build_ai_provider`).
  ///
  /// Throws [SidecarApiException] on any failure, like every other call here:
  /// "the sidecar did not answer" is not the same fact as "grading is
  /// unavailable", and a caller that conflated them would announce a
  /// configuration problem every time a request timed out.
  Future<GradingAvailabilityResponse> gradingAvailability({
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _api.gradingAvailabilityGradingAvailabilityGet(
        cancelToken: cancelToken,
      );
      return _requireBody(response);
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Score one answer. Throws [SidecarApiException] on any failure.
  Future<ScoreResponse> score({
    required String key,
    required int raw,
    required int maximum,
    CancelToken? cancelToken,
  }) async {
    try {
      final request = ScoreRequest(
        (builder) => builder
          ..key = key
          ..raw = raw
          ..maximum = maximum,
      );
      final response = await _api.scoreScorePost(
        scoreRequest: request,
        cancelToken: cancelToken,
      );
      final body = response.data;
      if (body == null) {
        throw SidecarApiException(
          SidecarErrorKind.badResponse,
          'sidecar returned an empty body',
          statusCode: response.statusCode,
        );
      }
      return body;
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// The registered tests available to import answers into (§16.4 test picker).
  /// Throws [SidecarApiException] on any failure.
  Future<List<TestSummary>> listTests({CancelToken? cancelToken}) async {
    try {
      final response = await _api.listTestsTestsGet(cancelToken: cancelToken);
      return (response.data ?? const <TestSummary>[]).toList();
    } on DioException catch (error) {
      throw _translate(error);
    }
  }

  /// Every submission imported for [testId], in intake order.
  /// Throws [SidecarApiException] on any failure.
  Future<List<SubmissionResponse>> listSubmissions(
    String testId, {
    CancelToken? cancelToken,
  }) async {
    try {
      final response = await _api.listSubmissionsTestsTestIdSubmissionsGet(
