    }
  }

  T _requireBody<T>(Response<T> response) {
    final body = response.data;
    if (body == null) {
      throw SidecarApiException(
        SidecarErrorKind.badResponse,
        'sidecar returned an empty body',
        statusCode: response.statusCode,
      );
    }
    return body;
  }

  DuplicateSubmissionException? _duplicateSubmission(DioException error) {
    if (error.response?.statusCode != 409) return null;
    final detail = error.response?.data is Map
        ? (error.response!.data as Map)['detail']
        : null;
    if (detail is! Map) return null;
    final existingId = detail['existing_submission_id'];
    if (existingId is! String) return null;
    final message = detail['message'];
    return DuplicateSubmissionException(
      message is String ? message : 'duplicate submission',
      existingId,
    );
  }

  /// Release the underlying HTTP connections.
  void close() {
    _dio.close(force: true);
    _uploadDio.close(force: true);
  }

  SidecarApiException _translate(DioException error) {
    switch (error.type) {
      case DioExceptionType.connectionTimeout:
      case DioExceptionType.connectionError:
        // No TCP connection to a loopback port within the budget means the
        // sidecar is not there, not that it is slow.
        return SidecarApiException(
          SidecarErrorKind.unavailable,
          'sidecar is not reachable',
        );
      case DioExceptionType.sendTimeout:
      case DioExceptionType.receiveTimeout:
      case DioExceptionType.transformTimeout:
        return SidecarApiException(
          SidecarErrorKind.timeout,
          'sidecar request timed out',
        );
      case DioExceptionType.cancel:
        return SidecarApiException(
          SidecarErrorKind.cancelled,
          'sidecar request was cancelled',
        );
      case DioExceptionType.badResponse:
        final status = error.response?.statusCode;
        if (status == 401) {
          return SidecarApiException(
            SidecarErrorKind.unauthorized,
            'sidecar rejected the bearer token',
            statusCode: status,
          );
        }
        if (status == 409) {
          return SidecarApiException(
            SidecarErrorKind.conflict,
            _detailMessage(error.response?.data) ??
                'sidecar reported a conflict',
            statusCode: status,
            unconfirmedQuestionIds: _detailQuestionIds(error.response?.data),
          );
        }
        return SidecarApiException(
          SidecarErrorKind.badResponse,
          _detailMessage(error.response?.data) ??
              'sidecar returned HTTP $status',
          statusCode: status,
        );
      case DioExceptionType.badCertificate:
      case DioExceptionType.unknown:
        return SidecarApiException(
          SidecarErrorKind.unknown,
          'unexpected sidecar error',
        );
    }
  }
}

/// FastAPI's `{"detail": "..."}` (or our own `{"detail": {"message": "..."}}`
/// shape for structured errors) -- pulls the human-readable text out so
/// callers see *why* a request failed, not just its status code.
String? _detailMessage(Object? data) {
  if (data is! Map) return null;
  final detail = data['detail'];
  if (detail is String) return detail;
  if (detail is Map && detail['message'] is String) {
    return detail['message'] as String;
  }
  return null;
}

/// `POST .../export`'s 409 body's `detail.question_ids` (Issue #23), or
/// `null` if absent/malformed -- see [SidecarApiException.unconfirmedQuestionIds].
List<String>? _detailQuestionIds(Object? data) {
  if (data is! Map) return null;
  final detail = data['detail'];
  if (detail is! Map) return null;
  final ids = detail['question_ids'];
  if (ids is! List) return null;
  return ids.whereType<String>().toList();
}

String _validatedLoopbackBaseUrl(String value) {
  const message = 'sidecar base URL must be an HTTP loopback URL with a port';
  late final Uri uri;
  try {
    uri = Uri.parse(value);
  } on FormatException {
    throw ArgumentError(message);
  }
  if (uri.scheme != 'http' ||
      uri.host != '127.0.0.1' ||
      !uri.hasPort ||
      (uri.path.isNotEmpty && uri.path != '/') ||
      uri.hasQuery ||
      uri.hasFragment ||
      uri.userInfo.isNotEmpty) {
    throw ArgumentError(message);
  }
  return uri.origin;
}
